#!/usr/bin/env bash
set -euo pipefail; source "$(dirname "$0")/common-demo.sh"; output="${1:-artifacts/deployment-certification.json}"; mkdir -p "$(dirname "$output")"; printf '{"project":"hashibot-demo","environment":"demo","runtime_mode":"shadow","mutation_authorized":false,"build_id":"%s","commit":"%s","services":[' "${BUILD_ID:-manual}" "${COMMIT_SHA:-unknown}" > "$output"
sep=''; for s in "${SERVICES[@]}"; do url=$(gcloud run services describe "hashibot-$s" --project "$PROJECT_ID" --region "$REGION" --format='value(status.url)'); token=$(gcloud auth print-identity-token); body=$(curl --fail --silent -H "Authorization: Bearer $token" "$url/health/version"); echo "$body" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{let x=JSON.parse(s);if(x.environment!=="demo"||x.runtime_mode!=="shadow"||x.mutation_authorized!==false)process.exit(1)})'; printf '%s{"service":"hashibot-%s","version":%s}' "$sep" "$s" "$body" >> "$output"; sep=,; done; printf ']}' >> "$output"
